{"results": [{"id": "FAM:SF-CHT-025", "label": "Study family SF-CHT-025: Play-type labeling audit: OTHER/DRIVE foul leakage", "score": 0.457, "reached_via": ["request matches the question or hypothesis of FAM:SF-CHT-025 (0.25)", "request matches RQC:RQC-087 (0.21); FAM:SF-CHT-025 auto_addresses_question RQC:RQC-087"], "attributes": {"observed_research_question": "Play-type labeling audit: OTHER/DRIVE foul leakage", "auto_outcome_status": "artifact", "observed_hypothesis": "Play-type PPP differences are real efficiency, not labeling/foul artifacts.", "observed_result": "OTHER: 36% end in fouls, PPP inflated (FOUL_BUCKET). DRIVE: 12pp below foul benchmark (FOUL_LEAK). PNR shows 22% foul rate. Only 335 of 50,668 possessions (0.7%) map to a real play type via initiation_type.", "auto_failure_mechanism": "C_artifact (apparent effect produced by a construction, selection or labelling flaw)", "observed_failure_evidence": "OTHER PPP inflated by 36% foul endings; DRIVE 12pp below foul benchmark; initiation_type maps 0.7%.", "observed_sample_and_power": "50,668 possessions in the initiation_type check", "auto_validation_status": "no_validation_recorded; evidence: NOT_RECORDED", "observed_method": "Per-PT diagnostic of foul-ending share vs PPP; initiation_type mapping.", "observed_verdict": "artifact_found"}, "relationships": []}, {"id": "FAM:SF07", "label": "Study family SF07: Sequential pair premium and defensive aftershock (8/8 PTs)", "score": 0.431, "reached_via": ["FAM:SF-APPA-050 auto_related_family (record_link_extends) FAM:SF07", "FAM:SF40 auto_related_family (record_link_related_to) FAM:SF07"], "attributes": {"observed_research_question": "Sequential pair premium and defensive aftershock (8/8 PTs)", "auto_outcome_status": "supported", "observed_hypothesis": "After the opponent runs play type X, the next offensive play type Y scores above Y's unconditional H2 baseline, and every PT has a defensive aftershock.", "observed_result": ["[APPA-049] A2 aftershock 8/8 PTs replicate all-games and playoffs (CUT +0.119 n=21,398 / PO +0.131 n=1,145 through TRANSITION +0.135 n=26,262 / +0.126 n=1,529). Top pair premiums: PUTBACK->TRANSITION +0.084 n=565; CUT->P [cut; read_family for the full text]", "[APPS-037] All-games aftershock after success: CUT +0.119 (n=21398), DRIVE +0.123 (57621), PNR +0.127 (51194), POST_UP +0.128 (20619), PULL_UP +0.132 (26060), PUTBACK +0.130 (5888), SPOT_UP +0.128 (43857), TRANSITION +0. [cut; read_family for the full text]"], "auto_failure_mechanism": "D_positive (no failure: positive result)"}, "relationships": [{"rel": "auto_limited_by", "node": "LIM:small_sample"}]}, {"id": "FAM:SF-APPA-050", "label": "Study family SF-APPA-050: Superstar sequential suppression: opponent play before the star", "score": 0.347, "reached_via": ["request matches the question or hypothesis of FAM:SF-APPA-050 (0.24)", "request matches VAR:PPP_points_per_possession (0.47); FAM:SF-APPA-050 auto_measures VAR:PPP_points_per_possession"], "attributes": {"observed_research_question": "Superstar sequential suppression: opponent play before the star", "auto_outcome_status": "not a hypothesis test", "observed_hypothesis": "A specific opponent play type on the preceding possession suppresses each star's next-possession PPP relative to that star's baseline.", "observed_result": "PUTBACK is top suppressor for 6+ stars (e.g. D. Mitchell 1.178 to 0.884, d=-0.294, n_after=95; B. Beal d=-0.345 n=32; C. Holmgren d=-0.222 n=52). Other tops: TRANSITION (A. Davis -0.058), POST_UP (N. Jokic -0.075), PULL_ [cut; read_family for the full text]", "auto_failure_mechanism": "E_unclear (mechanism unclear from the records)", "observed_failure_evidence": "No multiplicity correction; n_after is 32-95 for several PUTBACK cells vs thousands of baseline possessions.", "observed_sample_and_power": "30 stars; min n_after=30", "auto_validation_status": "no_validation_recorded; evidence: NOT_RECORDED"}, "relationships": [{"rel": "auto_has_risk", "node": "RISK:DRIFT_NONSTATIONARITY"}]}, {"id": "FAM:SF-APPM-022", "label": "Study family SF-APPM-022: Superstar suppression profiles (incl. Q5c sequential triggering)", "score": 0.347, "reached_via": ["FAM:SF-APPA-050 auto_related_family (repeated_by_later_family) FAM:SF-APPM-022", "FAM:SF-APPA-050 auto_related_family (repeat_of_earlier_family) FAM:SF-APPM-022"], "attributes": {"observed_research_question": "Superstar suppression profiles (incl. Q5c sequential triggering)", "auto_outcome_status": "inconclusive", "observed_hypothesis": "Specific opposing lineups, defenders, play types and preceding opponent play types suppress star efficiency.", "observed_result": "Q5c verdict 'rank-1 suppressor varies meaningfully across players'; e.g. Jokic after opp POST_UP 1.1271 (-0.0675, SE +/-0.0500, n=480); Curry forced POST_UP -0.209.", "auto_failure_mechanism": "E_unclear (mechanism unclear from the records)", "observed_failure_evidence": "Rank-1 deltas mostly within 1-2 SE with no multiple-comparison control; OTHER artifact flagged in doc.", "observed_sample_and_power": "SE per cell reported", "auto_validation_status": "no_validation_recorded; evidence: NOT_RECORDED", "observed_verdict": "inconclusive", "observed_failure_type": "E_unclear", "observed_notes": "NOT_RECORDED", "auto_confidence": "medium (0.65)"}, "relationships": [{"rel": "auto_related_family", "node": "FAM:SF-APPA-050"}]}], "n_results": 4}

